        dp[1][k][n] = 0;
        RMQ[] rmq = new RMQ[2];
        rmq[0] = new RMQ(dp[0][k]);
        rmq[1] = new RMQ(dp[1][k]);
        for(int i = k-1; i >= 0; i--){
            for(int j = 0;j <= 2*n; j++){
                dp[0][i][j] = j+l[i]+delt[i] <= 2*n ? dp[0][i+1][j+l[i]+delt[i]] : n;
                dp[1][i][j] = dp[1][i+1][j];
                dp[0][i][j] = Math.min(dp[0][i][j] , 1 + rmq[1].min(j , Math.min(j+l[i] , 2*n)));
                if(j + delt[i] <= 2*n)dp[1][i][j] = Math.min(dp[1][i][j] , 1 + rmq[0].min(j + delt[i] , Math.min(j+l[i] + delt[i] , 2*n)));
