    public static class RMQ{
        int n , k;
        int[][] min;
        public RMQ(int[] a){
            n = a.length;
            k = Integer.numberOfTrailingZeros(Integer.highestOneBit(n))+1;
            min = new int[k][n];
            for(int i = 0;i < n; i++)
                min[0][i] = a[i];
            for(int i = 1; i < k; i++){
