#include <bits/stdc++.h>
using namespace std;

/*
TASK: cutlet
LANG: C++
 */

struct RMQ {
    int n, k;
    std::vector<std::vector<int>> min;
    RMQ(const std::vector<int>& a) {
        n = a.size();
        k = std::numeric_limits<int>::digits - __builtin_clz(n);
        min.assign(k, std::vector<int>(n));
        for (int i = 0; i < n; i++) {
            min[0][i] = a[i];
        }
        for (int i = 1; i < k; i++) {
            for (int j = 0; j + (1 << (i - 1)) < n; j++) {
                min[i][j] = std::min(min[i - 1][j], min[i - 1][j + (1 << (i - 1))]);
            }
        }
    }
    int min_query(int a, int b) {
        int z = __builtin_ctz(b - a + 1);
        return std::min(min[z][a], min[z][b - (1 << z) + 1]);
    }
};

struct FastScanner {
    std::istream& stream;
    char buf[1024];
    int curChar = 0, numChars = 0;

    FastScanner(std::istream& s) : stream(s) {}

    int read() {
        if (numChars == -1)
            throw std::runtime_error("InputMismatch");
        if (curChar >= numChars) {
            curChar = 0;
            numChars = stream.readsome(buf, 1024);
            if (numChars <= 0) return -1;
        }
        return buf[curChar++];
    }

    bool isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    bool isEndline(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }

    int nextInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int res = 0;
        do {
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res;
    }

    long long nextLong() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        long long res = 0;
        do {
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res;
    }

    double nextDouble() {
        // Not used in original code, so omitted for brevity
        return 0.0;
    }

    std::string next() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        std::string res;
        do {
            res += static_cast<char>(c);
            c = read();
        } while (!isSpaceChar(c));
        return res;
    }

    std::string nextLine() {
        int c = read();
        while (isEndline(c))
            c = read();
        std::string res;
        do {
            res += static_cast<char>(c);
            c = read();
        } while (!isEndline(c));
        return res;
    }
};

int main() {
    FastScanner in(std::cin);
    int n = in.nextInt();
    int k = in.nextInt();

    std::vector<std::array<int, 2>> segs(k);
    for (int i = 0; i < k; i++) {
        segs[i][0] = in.nextInt();
        segs[i][1] = in.nextInt();
    }

    std::sort(segs.begin(), segs.end(), [](const std::array<int, 2>& a, const std::array<int, 2>& b) {
        return a[0] < b[0];
    });

    std::vector<std::array<int, 2>> finSeg;
    for (int i = 0; i < k; i++) {
        int lo = segs[i][0];
        int hi = segs[i][0];
        int j = i;
        while (j < k && segs[j][0] <= hi) {
            hi = std::max(hi, segs[j][1]);
            j++;
        }
        finSeg.push_back({lo, hi});
        i = j - 1;
    }
    k = finSeg.size();

    std::vector<std::array<int, 2>> segsArr(k);
    std::vector<int> l(k), delt(k);
    for (int i = 0; i < k; i++) {
        segsArr[i] = finSeg[i];
    }
    for (int i = 0; i < k; i++) {
        l[i] = segsArr[i][1] - segsArr[i][0];
        if (i < k - 1)
            delt[i] = segsArr[i + 1][0] - segsArr[i][1];
        else
            delt[i] = 2 * n - segsArr[i][1];
    }

    std::vector<std::vector<int>> dp0(k + 1, std::vector<int>(2 * n + 1, n));
    std::vector<std::vector<int>> dp1(k + 1, std::vector<int>(2 * n + 1, n));

    dp0[k][n] = 0;
    dp1[k][n] = 0;

    std::vector<RMQ> rmq0, rmq1;
    rmq0.emplace_back(dp0[k]);
    rmq1.emplace_back(dp1[k]);

    for (int i = k - 1; i >= 0; i--) {
        for (int j = 0; j <= 2 * n; j++) {
            int val0 = (j + l[i] + delt[i] <= 2 * n) ? dp0[i + 1][j + l[i] + delt[i]] : n;
            dp0[i][j] = val0;

            int val1 = dp1[i + 1][j];
            dp1[i][j] = val1;

            int minVal0 = 1 + rmq1.back().min_query(j, std::min(j + l[i], 2 * n));
            dp0[i][j] = std::min(dp0[i][j], minVal0);

            if (j + delt[i] <= 2 * n) {
                int val0_alt = 1 + rmq0.back().min_query(j + delt[i], std::min(j + l[i] + delt[i], 2 * n));
                dp0[i][j] = std::min(dp0[i][j], val0_alt);

                int val1_alt = 2 + rmq0.back().min_query(j + delt[i], std::min(j + l[i] + delt[i], 2 * n));
                dp1[i][j] = std::min(dp1[i][j], val1_alt);
            }

            int val1_alt2 = 2 + rmq1.back().min_query(j, std::min(j + l[i], 2 * n));
            dp1[i][j] = std::min(dp1[i][j], val1_alt2);
        }
        rmq0.emplace_back(dp0[i]);
        rmq1.emplace_back(dp1[i]);
    }

    int ans = dp1[0][0];
    if (ans == n) {
        std::cout << "Hungry\n";
    } else {
        std::cout << "Full\n" << ans << "\n";
    }
    return 0;
}

